const ELEMENT_PROP_KEYS = new Set(["theme","beat","fontWeight","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  beat: 30,
  fontWeight: 300,
  accent: "#3B5BFD",
  fontFamily: "Sora",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type ConcentricScaleElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ConcentricScaleBase>;

const ConcentricScaleInner = forwardRef<
  HTMLDivElement,
  ConcentricScaleElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ConcentricScale>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ConcentricScaleBase
          {...(componentProps as unknown as ComponentProps<typeof ConcentricScaleBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ConcentricScale = Interactive.withSchema({
  Component: ConcentricScaleInner,
  componentName: "<ConcentricScale>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
